<script setup lang="ts">
import { tUi } from '../i18n'

import { serverConnectionLabel } from '../serverConnection'
import { useAppScope } from '../composables/useAppScope'
import CommitHash from '../components/CommitHash.vue'
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, Plus } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { errorText, http, normalizeRelease, normalizeService, payload, rows, serviceRequest } from '../api'
import type { DeploymentServer, Release, Service, ServiceEnvironment } from '../types'
import { environmentLabel, statusLabel, statusType, formatTime, timeParts, windowsCommand } from '../ui'
import MobileBuildSettings from '../components/MobileBuildSettings.vue'
import BuildEngineSelect from '../components/BuildEngineSelect.vue'
import AppIntegrationAccess from '../components/AppIntegrationAccess.vue'
import { isMobileDraft, mobileBuildDefaults, mobileBuildError, mobileFormat, mobileVersionLabel } from '../mobile'
import ServiceIdentity from '../components/ServiceIdentity.vue'
import ServiceIconPicker from '../components/ServiceIconPicker.vue'
import AppArtifactVersions from '../components/AppArtifactVersions.vue'

type EnvName='dev'|'test'|'prod'
const mobileSettings=ref<{commitParameters:()=>boolean}>()
const { apps, api, buildPath, releasePath } = useAppScope()
const route=useRoute(),router=useRouter(),id=route.params.id,loading=ref(true),saving=ref(false),tab=ref(apps?String(route.query.tab||'mobile'):'basic'),loadError=ref(''),artifacts=ref<Record<string,unknown>[]>([]),builds=ref<Release[]>([]),releases=ref<Release[]>([]),servers=ref<DeploymentServer[]>([]),activeEnv=ref<EnvName>('dev')
const artifactLoading=ref(false),artifactsLoaded=ref(false),artifactError=ref('')
let artifactRequest=0,artifactController:AbortController|undefined
const model=reactive<Service>({name:'',code:'',serviceType:'BACKEND',buildEngine:'GITHUB',imageBuildMode:'REPOSITORY_DOCKERFILE',description:'',status:true,gitUrl:'',defaultBranch:'main',buildTool:'Maven',buildCommand:'./mvnw clean package -DskipTests',jarPath:'target/*.jar',dockerfilePath:'Dockerfile',imageRepository:'',imageName:'',environment:'test',deployHost:'',deployPort:8080,containerPort:8080,envVariables:[]})
function environmentDefault(name:EnvName):ServiceEnvironment{return{environmentName:name,serverIds:[],hostPort:8080,containerPort:8080,containerName:'',envFilePath:'',dockerNetwork:'',restartPolicy:'UNLESS_STOPPED',deploymentMode:'DOCKER_RUN',composeService:'',startCommand:'',healthCheckUrl:'',envJson:'{}',envVariables:[],enabled:true}}
const environmentConfigs=reactive<Record<EnvName,ServiceEnvironment>>({dev:environmentDefault('dev'),test:environmentDefault('test'),prod:environmentDefault('prod')})
const appEnabled=computed(()=>model.status!==false&&model.status!=='DISABLED')
const isMobile=computed(()=>model.serviceType==='FLUTTER_ANDROID')
const isFrontend=computed(()=>model.serviceType==='FRONTEND')
const repositoryDockerfileMode=computed(()=>isFrontend.value&&model.imageBuildMode==='REPOSITORY_DOCKERFILE')
const currentEnvironment=computed(()=>environmentConfigs[activeEnv.value])
const selectedServers=computed(()=>currentEnvironment.value.serverIds.map(serverId=>servers.value.find(server=>String(server.id)===String(serverId))).filter(Boolean) as DeploymentServer[])
function addEnv(){currentEnvironment.value.envVariables.push({key:'',value:'',secret:false})}
function frontendCommand(tool:string){return tool==='pnpm'?'pnpm install --frozen-lockfile && pnpm run build':tool==='yarn'?'yarn install --frozen-lockfile && yarn build':'npm ci && npm run build'}
function buildToolChanged(value:string){if(isFrontend.value)model.buildCommand=frontendCommand(value);else model.buildCommand=value==='Gradle'?'./gradlew clean build -x test':'mvn clean package -DskipTests'}
function parseEnvironment(raw:Record<string,unknown>):ServiceEnvironment{let values:Record<string,unknown>={};try{values=JSON.parse(String(raw.envJson||'{}'))}catch{}return{...environmentDefault(String(raw.environmentName) as EnvName),...raw,serverIds:Array.isArray(raw.serverIds)?raw.serverIds as Array<number|string>:[],envVariables:Object.entries(values).map(([key,value])=>({key,value:String(value??''),secret:false}))} as ServiceEnvironment}
async function load(){loading.value=true;try{const [serviceResult,serverResult,environmentResult]=await Promise.all([http.get(api(`/services/${id}`)),apps?Promise.resolve({data:[]}):http.get(api('/servers')),apps?Promise.resolve({data:[]}):http.get(api(`/services/${id}/environments`))]);Object.assign(model,normalizeService(payload<Record<string,unknown>>(serviceResult,{})));model.serviceType=model.serviceType||'BACKEND';if(apps&&model.serviceType!=='FLUTTER_ANDROID')throw new Error(tUi('该应用不存在或无 App 访问权限'));loadError.value='';if(isMobile.value)model.mobileBuild={...mobileBuildDefaults(),...model.mobileBuild};servers.value=rows<DeploymentServer>(serverResult.data);for(const raw of rows<Record<string,unknown>>(environmentResult.data)){const config=parseEnvironment(raw);if(['dev','test','prod'].includes(config.environmentName))Object.assign(environmentConfigs[config.environmentName],config)}}catch(e){loadError.value=errorText(e);ElMessage.error(loadError.value)}finally{loading.value=false}}
async function loadArtifacts(force=false){
  if(artifactLoading.value||artifactsLoaded.value&&!force)return
  const request=++artifactRequest;artifactController?.abort();const controller=new AbortController();artifactController=controller
  artifactLoading.value=true;artifactError.value=''
  try{
    const result=rows<Record<string,unknown>>((await http.get(api('/artifacts'),{params:{serviceId:id},signal:controller.signal})).data)
    const enriched=isMobile.value?await Promise.all(result.map(async item=>{try{return {...item,...payload<Record<string,unknown>>(await http.get(api(`/mobile/artifacts/${item.id}`),{signal:controller.signal}),{}),id:item.id}}catch{return {...item,_detailsUnavailable:true}}})):result
    if(request!==artifactRequest)return
    artifacts.value=enriched;artifactsLoaded.value=true
  }catch(error){if(request!==artifactRequest)return;artifacts.value=[];artifactsLoaded.value=false;artifactError.value=errorText(error,tUi('暂时无法读取安装包版本'))}
  finally{if(request===artifactRequest)artifactLoading.value=false}
}
async function loadTab(name:string){if(name==='artifacts')await loadArtifacts();if(name==='builds'&&!builds.value.length)try{builds.value=rows<Record<string,unknown>>((await http.get(api('/builds'),{params:{serviceId:id}})).data).map(normalizeRelease)}catch(error){ElMessage.error(errorText(error,tUi('读取历史记录失败')))};if(name==='releases'&&!releases.value.length)try{releases.value=rows<Record<string,unknown>>((await http.get(api('/releases'),{params:{serviceId:id}})).data).map(normalizeRelease)}catch(error){ElMessage.error(errorText(error,tUi('读取历史记录失败')))}}
function tabChanged(name: string | number){loadTab(String(name));if(apps)router.replace({query:{...route.query,tab:String(name)}})}
async function save(){if(saving.value||loading.value||loadError.value)return;if(isMobile.value&&mobileSettings.value&&!mobileSettings.value.commitParameters())return;if((!repositoryDockerfileMode.value&&windowsCommand(model.buildCommand))||windowsCommand(model.workDirectory))return ElMessage.warning(tUi('构建运行在 Linux 服务器，请改用 Linux 命令和相对路径'));if(isMobile.value&&(!apps||appEnabled.value)){const reason=mobileBuildError(model.mobileBuild);if(reason)return ElMessage.warning(reason)}saving.value=true;try{await http.put(api(`/services/${id}`),serviceRequest(model));if(!isMobile.value)for(const name of ['dev','test','prod'] as EnvName[]){const config=environmentConfigs[name],env=Object.fromEntries(config.envVariables.filter(v=>v.key).map(v=>[v.key,v.value]));await http.put(api(`/services/${id}/environments/${name}`),{...config,serverIds:config.serverIds.map(Number),envJson:JSON.stringify(env)})}ElMessage.success(isMobile.value?tUi('App 服务配置已保存'):tUi('服务与三套环境配置已保存'))}catch(e){ElMessage.error(errorText(e))}finally{saving.value=false}}
onBeforeUnmount(()=>{++artifactRequest;artifactController?.abort()})
onMounted(async()=>{await load();if(!loadError.value)await loadTab(tab.value)})
</script>

<template>
  <div class="page-head"><div style="min-width:0"><el-button link :icon="ArrowLeft" @click="router.push(apps?'/apps':'/services')">{{apps?tUi('返回 App 发布'):tUi('返回服务列表')}}</el-button><h2 style="margin-top:14px"><ServiceIdentity :service="model" large/></h2><p>{{model.description||(apps?tUi('配置应用、构建安装包并追踪各环境交付。'):tUi('管理代码仓库、构建方式与部署环境。'))}}</p></div><div class="actions"><el-button v-if="apps" :disabled="loading||!!loadError||!appEnabled||!!mobileBuildError(model.mobileBuild)" @click="router.push(`/apps/${id}/build`)">{{ tUi('新建构建') }}</el-button><el-button type="primary" :loading="saving" :disabled="loading||!!loadError" @click="save">{{apps&&!appEnabled?tUi('保存配置草稿'):tUi('保存配置')}}</el-button></div></div>
  <el-alert v-if="loadError" :title="loadError" type="error" :closable="false" show-icon/><section v-else class="panel" v-loading="loading">
    <el-alert v-if="!loading && isMobileDraft(model)" class="mobile-draft-notice" :title="tUi('待配置（未启用）')" :description="tUi('已登记代码仓库。请在 App 构建配置中补充固定 Flutter 版本，并完成至少一个环境的包名和签名配置；完成配置并启用后，才能选择此服务打包。')" type="info" :closable="false" show-icon style="margin-bottom:20px"/>
    <el-tabs v-model="tab" @tab-change="tabChanged">
      <el-tab-pane :label="tUi('基础信息配置')" name="basic"><div class="form-section"><h4>{{ tUi('基础信息') }}</h4><el-form label-position="top"><el-form-item :label="tUi('服务图标')"><ServiceIconPicker v-model="model.displayIcon" :service-type="model.serviceType" :code="model.code"/></el-form-item><div class="two"><el-form-item :label="tUi('服务名称')"><el-input v-model="model.name"/></el-form-item><el-form-item :label="tUi('服务标识')"><el-input v-model="model.code" disabled/></el-form-item></div><el-form-item :label="tUi('服务描述')"><el-input v-model="model.description" type="textarea" :rows="3"/></el-form-item><el-form-item><el-switch v-model="model.status" :active-text="apps?tUi('启用 App 构建'):tUi('启用服务')"/><p v-if="apps" class="field-help">{{ tUi('启用前需完成 Flutter 和至少一个环境的包名与签名配置；未启用时可保存草稿。') }}</p></el-form-item></el-form></div></el-tab-pane>
      <el-tab-pane :label="tUi('Git 配置')" name="git"><div class="form-section"><h4>{{ tUi('代码仓库') }}</h4><el-form label-position="top"><el-form-item :label="tUi('仓库地址')"><el-input v-model="model.gitUrl" placeholder="git@github.com:team/project.git"/></el-form-item><div class="two"><el-form-item :label="tUi('默认分支')"><el-input v-model="model.defaultBranch"/></el-form-item><el-form-item :label="tUi('认证方式')"><el-select v-model="model.gitAuthType" style="width:100%"><el-option label="SSH Key" value="SSH"/><el-option label="Access Token" value="TOKEN"/><el-option :label="tUi('用户名密码')" value="PASSWORD"/></el-select></el-form-item></div><el-form-item :label="tUi('凭据标识')"><el-input v-model="model.gitCredential" :placeholder="tUi('敏感凭据由后端加密保存')" show-password/></el-form-item></el-form></div></el-tab-pane>
      <el-tab-pane v-if="!isMobile" :label="tUi('构建配置')" name="build"><div class="form-section"><h4>{{isFrontend?tUi('Node 前端构建'):tUi('Spring Boot JAR 构建')}}</h4><el-form label-position="top"><BuildEngineSelect v-model="model.buildEngine" :disabled="loading||saving"/><el-alert v-if="repositoryDockerfileMode" :title="tUi('当前由仓库 Dockerfile 完成依赖安装和应用构建，平台不会在宿主机重复执行下方 Node 构建命令。')" type="info" :closable="false" show-icon style="margin-bottom:16px"/><div class="two"><el-form-item :label="isFrontend?tUi('包管理器'):tUi('构建工具')"><el-select v-model="model.buildTool" style="width:100%" :disabled="repositoryDockerfileMode" @change="buildToolChanged"><template v-if="isFrontend"><el-option label="npm" value="npm"/><el-option label="pnpm" value="pnpm"/><el-option label="yarn" value="yarn"/></template><template v-else><el-option label="Maven" value="Maven"/><el-option label="Gradle" value="Gradle"/></template></el-select></el-form-item><el-form-item v-if="!isFrontend" :label="tUi('Java 版本')"><el-input model-value="Java 21（平台构建环境）" disabled/></el-form-item><el-form-item v-else :label="tUi('运行环境')"><el-input :value="repositoryDockerfileMode?'由仓库 Dockerfile 决定':'Node.js 22（平台构建环境）'" disabled/></el-form-item></div><el-alert v-if="(!repositoryDockerfileMode&&windowsCommand(model.buildCommand)) || windowsCommand(model.workDirectory)" :title="tUi('检测到 Windows 命令或路径，请改为 Linux 配置后保存。')" type="warning" :closable="false" show-icon style="margin-bottom:16px"/><el-form-item :label="tUi('构建命令')"><el-input v-model="model.buildCommand" class="mono" :disabled="repositoryDockerfileMode" :placeholder="isFrontend?'npm ci && npm run build':'mvn clean package -DskipTests'"/></el-form-item><div class="two"><el-form-item :label="tUi('工作目录')"><el-input v-model="model.workDirectory" :disabled="repositoryDockerfileMode" :placeholder="tUi('默认仓库根目录，例如 frontend')"/></el-form-item><el-form-item :label="isFrontend?tUi('输出目录'):tUi('JAR 匹配路径')"><el-input v-model="model.jarPath" :disabled="repositoryDockerfileMode" :placeholder="isFrontend?'dist':'target/*.jar'"/></el-form-item></div><el-form-item :label="tUi('构建超时（分钟）')"><el-input-number v-model="model.buildTimeout" :min="1" :max="180"/></el-form-item></el-form></div></el-tab-pane>
      <el-tab-pane v-if="!isMobile" :label="tUi('镜像配置')" name="image"><div class="form-section"><h4>{{ tUi('容器镜像') }}</h4><el-form label-position="top"><el-form-item v-if="isFrontend" :label="tUi('前端交付方式')" required><el-radio-group v-model="model.imageBuildMode"><el-radio-button value="STATIC_NGINX">{{ tUi('静态站点（Nginx）') }}</el-radio-button><el-radio-button value="REPOSITORY_DOCKERFILE">{{ tUi('Node 应用（仓库 Dockerfile）') }}</el-radio-button></el-radio-group><div class="field-help">{{ tUi('已有前端默认保持“静态站点”；只有需要持续运行 Node、服务端渲染或提供接口的项目才选择“Node 应用”。') }}</div></el-form-item><el-alert v-if="repositoryDockerfileMode" :title="tUi('平台将直接使用仓库 Dockerfile，并固定以源码根目录作为 docker build 上下文。')" type="info" :closable="false" show-icon style="margin-bottom:16px"/><el-alert v-else-if="isFrontend" :title="tUi('平台保持现有链路：先生成静态文件，再自动制作 Nginx 镜像。')" type="info" :closable="false" show-icon style="margin-bottom:16px"/><el-form-item :label="tUi('完整镜像仓库地址')"><el-input v-model="model.imageRepository" placeholder="registry.example.com/team/service-name"/></el-form-item><div class="two"><el-form-item :label="tUi('镜像名称')"><el-input v-model="model.imageName" :placeholder="model.code"/></el-form-item><el-form-item :label="tUi('Dockerfile 路径')"><el-input v-model="model.dockerfilePath" :disabled="isFrontend&&!repositoryDockerfileMode" placeholder="Dockerfile"/><div class="muted" style="margin-top:6px">{{repositoryDockerfileMode?tUi('相对源码根目录填写，例如 Dockerfile 或 deploy/Dockerfile。'):isFrontend?tUi('静态模式由平台生成 Dockerfile，无需调整。'):tUi('相对工作目录填写。')}}</div></el-form-item></div><el-alert :title="tUi('镜像仓库认证由平台基础配置统一管理。')" type="info" :closable="false" show-icon/></el-form></div></el-tab-pane>
      <el-tab-pane v-if="isMobile" :label="tUi('App 构建配置')" name="mobile"><div class="form-section"><h4>Flutter Android · {{mobileFormat(model.mobileBuild)==='APK'?tUi('完整 APK'):'AAB'}}</h4><el-form label-position="top"><BuildEngineSelect v-model="model.buildEngine" :disabled="loading||saving"/><MobileBuildSettings v-if="model.mobileBuild" ref="mobileSettings" :model="model.mobileBuild"/><el-form-item :label="tUi('项目工作目录')"><el-input v-model="model.workDirectory" :placeholder="tUi('默认仓库根目录')"/></el-form-item></el-form></div></el-tab-pane>
      <el-tab-pane v-if="isMobile" :label="tUi('发布环境')" name="mobile-environments"><div class="form-section"><h4>{{ tUi('按环境交付安装包') }}</h4><p class="artifact-storage-note">{{ tUi('构建时选择开发、预生产或生产，安装包只能交付到相同环境。包名、签名和地址随构建锁定，每条发布记录独立拉取并确认结果。') }}</p><el-table :data="[{name:tUi('开发'),merge:tUi('不合并')},{name:tUi('预生产'),merge:tUi('不合并')},{name:tUi('生产'),merge:tUi('启用自动合回时，发布成功后合并已验证的提交')}]"><el-table-column prop="name" :label="tUi('发布环境')"/><el-table-column :label="tUi('交付方式')"><template #default>{{ tUi('拉取安装包，再确认实际发布结果') }}</template></el-table-column><el-table-column prop="merge" :label="tUi('代码合回')"/></el-table><p class="artifact-storage-note">{{ tUi('在“App 构建配置”中分别配置并启用环境。历史包若未记录构建环境，需要重新构建后才能创建新交付。生产发布仍需当前登录账号的动态码确认；下载完成不会自动标记发布成功。') }}</p></div></el-tab-pane>
      <el-tab-pane v-if="isMobile" :label="tUi('接口对接')" name="integration"><AppIntegrationAccess v-if="tab==='integration' && String(model.id)===String(route.params.id)" :key="String(route.params.id)" :service-id="String(route.params.id)" :service-name="model.name"/></el-tab-pane>
      <el-tab-pane v-if="!isMobile" :label="tUi('环境与集群')" name="deploy">
        <div class="environment-layout">
          <div class="environment-head"><div><h4>{{ tUi('部署环境') }}</h4><p>{{ tUi('每个环境都是一个集群，可以绑定一台或多台服务器。') }}</p></div><el-button :icon="Plus" @click="router.push('/servers')">{{ tUi('管理服务器') }}</el-button></div>
          <el-tabs v-model="activeEnv" type="card" class="environment-tabs">
            <el-tab-pane :label="tUi('开发环境')" name="dev"/><el-tab-pane :label="tUi('预生产环境')" name="test"/><el-tab-pane :label="tUi('生产环境')" name="prod"/>
          </el-tabs>
          <el-form label-position="top" class="environment-form">
            <div class="environment-status"><div><b>{{activeEnv==='dev'?tUi('开发环境'):activeEnv==='test'?tUi('预生产环境'):tUi('生产环境')}}</b><span>{{ tUi('已选择 {0} 个集群节点', selectedServers.length) }}</span></div><el-switch v-model="currentEnvironment.enabled" :active-text="tUi('允许发版')"/></div>
            <el-form-item :label="tUi('集群服务器')" required>
              <el-select v-model="currentEnvironment.serverIds" multiple filterable collapse-tags :max-collapse-tags="3" :placeholder="tUi('请选择一台或多台服务器')" style="width:100%">
                <el-option v-for="server in servers.filter(item=>item.enabled)" :key="server.id" :value="server.id!" :label="`${server.name} · ${serverConnectionLabel(server,{includeAuth:true})}`"/>
              </el-select>
              <div v-if="!servers.length" class="field-help">{{ tUi('还没有服务器，请先点击右上角“管理服务器”添加。') }}</div>
            </el-form-item>
            <div v-if="selectedServers.length" class="cluster-nodes"><div v-for="server in selectedServers" :key="server.id"><span class="status-dot status-success"></span><b>{{server.name}}</b><small>{{server.connectionMode==='SSH_CONFIG'?serverConnectionLabel(server):`${server.host} · ${server.authType==='PASSWORD'?tUi('密码'):'SSH Key'}`}}</small></div></div>
            <el-form-item :label="tUi('部署方式')"><el-radio-group v-model="currentEnvironment.deploymentMode"><el-radio-button value="DOCKER_RUN">{{ tUi('直接运行容器') }}</el-radio-button><el-radio-button value="DOCKER_COMPOSE">Docker Compose</el-radio-button></el-radio-group></el-form-item>
            <template v-if="currentEnvironment.deploymentMode==='DOCKER_RUN'">
              <el-alert type="info" :closable="false" show-icon :title="tUi('平台会按容器名称删除旧容器，再使用本次选择的镜像启动同名新容器；不需要 sudo。')"/>
              <div class="two" style="margin-top:18px"><el-form-item :label="tUi('宿主机端口')"><el-input-number v-model="currentEnvironment.hostPort" :min="1" :max="65535" style="width:100%"/></el-form-item><el-form-item :label="tUi('容器端口')"><el-input-number v-model="currentEnvironment.containerPort" :min="1" :max="65535" style="width:100%"/></el-form-item></div>
              <el-form-item :label="tUi('容器名称')" required><el-input v-model="currentEnvironment.containerName" :placeholder="model.code"/><div class="field-help">{{ tUi('必须与服务器上原有容器名称完全一致，例如 {0}。', model.code) }}</div></el-form-item>
              <div class="two"><el-form-item :label="tUi('远程环境变量文件')"><el-input v-model="currentEnvironment.envFilePath" placeholder="/srv/services/env/service.env"/><div class="field-help">{{ tUi('留空表示不使用 --env-file，平台不会读取或修改该文件内容。') }}</div></el-form-item><el-form-item :label="tUi('Docker 网络')"><el-input v-model="currentEnvironment.dockerNetwork" placeholder="service-net"/></el-form-item></div>
              <el-form-item :label="tUi('容器重启策略')"><el-select v-model="currentEnvironment.restartPolicy" style="width:100%"><el-option :label="tUi('不自动重启（与未配置 --restart 一致）')" value="NO"/><el-option :label="tUi('除非手动停止，否则重启')" value="UNLESS_STOPPED"/><el-option :label="tUi('始终重启')" value="ALWAYS"/><el-option :label="tUi('异常退出时重启')" value="ON_FAILURE"/></el-select></el-form-item>
            </template>
            <template v-else>
              <el-alert type="info" :closable="false" show-icon :title="tUi('平台只覆盖镜像版本，Compose 中原有的环境变量、挂载目录、网络和依赖关系都会保留。')"/>
              <div class="two" style="margin-top:18px"><el-form-item :label="tUi('Compose 服务名')" required><el-input v-model="currentEnvironment.composeService" :placeholder="model.code"/><div class="field-help">{{ tUi('默认与服务标识一致，例如 {0}。', model.code) }}</div></el-form-item><el-form-item :label="tUi('容器内部健康检查端口')"><el-input-number v-model="currentEnvironment.containerPort" :min="1" :max="65535" style="width:100%"/></el-form-item></div>
            </template>
            <el-form-item :label="tUi('健康检查地址')"><el-input v-model="currentEnvironment.healthCheckUrl" :placeholder="currentEnvironment.deploymentMode==='DOCKER_COMPOSE'?tUi('例如 /healthz'):tUi('例如 http://{host}:{hostPort}/healthz')"/><div class="field-help">{{currentEnvironment.deploymentMode==='DOCKER_COMPOSE'?tUi('平台会从服务器内找到 Compose 容器地址进行检查，不要求映射宿主机端口。'):tUi('使用 {host} 表示当前节点地址，平台会逐台检查；留空时使用默认地址。')}}</div></el-form-item>
            <div class="panel-title env-title"><div><b>{{ tUi('环境变量') }}</b><small>{{ tUi('仅注入当前环境的容器') }}</small></div><el-button :icon="Plus" @click="addEnv">{{ tUi('添加变量') }}</el-button></div>
            <div v-if="currentEnvironment.envVariables.length"><div v-for="(item,index) in currentEnvironment.envVariables" :key="index" class="env-row"><el-input v-model="item.key" :placeholder="tUi('变量名，例如 APP_MODE')"/><el-input v-model="item.value" :placeholder="tUi('变量值')" :type="item.secret?'password':'text'" show-password/><el-checkbox v-model="item.secret">{{ tUi('敏感') }}</el-checkbox><el-button link type="danger" @click="currentEnvironment.envVariables.splice(index,1)">{{ tUi('删除') }}</el-button></div></div>
            <div v-else class="environment-empty">{{ tUi('当前环境暂无环境变量') }}</div>
          </el-form>
        </div>
      </el-tab-pane>
      <el-tab-pane :label="apps?tUi('构建记录'):tUi('打包记录')" name="builds">
        <el-table v-if="builds.length" :data="builds" class="clickable-table" @row-click="(row: Release) => router.push(buildPath(row.id))">
          <el-table-column :label="tUi('创建时间 / 任务')" width="165"><template #default="{row}"><div class="record-time" :title="timeParts(row.createdAt).full"><b>{{timeParts(row.createdAt).time}}</b><span>{{timeParts(row.createdAt).date}}</span><small>#{{row.id}}</small></div></template></el-table-column>
          <el-table-column :label="tUi('分支 / Commit')" min-width="220"><template #default="{row}"><b class="record-branch" :title="row.branch">{{row.branch || tUi('未记录分支')}}</b><CommitHash :value="row.commitId"/></template></el-table-column>
          <el-table-column v-if="isMobile" :label="tUi('App 版本')" min-width="160"><template #default="{row}"><b class="artifact-version-label">{{mobileVersionLabel(row)}}</b></template></el-table-column><el-table-column v-if="isMobile" :label="tUi('构建环境')" width="125"><template #default="{row}">{{row.environment?environmentLabel(row.environment):tUi('历史记录未保存')}}<small class="artifact-repository">{{row.mobileBuildMode || ''}}</small></template></el-table-column><el-table-column :label="tUi('状态')" width="120"><template #default="{row}"><el-tag :type="statusType(row.status)" size="small">{{statusLabel(row.status)}}</el-tag></template></el-table-column>
          <el-table-column :label="tUi('打包人')" min-width="100"><template #default="{row}">{{row.createdBy || '—'}}</template></el-table-column>
          <el-table-column :label="tUi('操作')" width="90" fixed="right"><template #default="{row}"><el-button link type="primary" @click.stop="router.push(buildPath(row.id))">{{ tUi('详情') }}</el-button></template></el-table-column>
        </el-table><div v-else class="empty"><div><strong>{{ tUi('暂无打包记录') }}</strong><p>{{apps?tUi('点击页面顶部“新建构建”，完成后即可交付安装包。'):tUi('从“打包记录”中新建任务，完成后即可选择镜像版本发布。')}}</p></div></div>
      </el-tab-pane>
      <el-tab-pane :label="apps?tUi('安装包版本'):tUi('制品包')" name="artifacts">
        <div class="artifact-storage-note">{{isMobile?tUi('这里保存通过包名、版本与签名校验的安装包。创建指定环境的发布记录后即可下载和确认交付。'):tUi('这里保存成功构建的版本记录，发布时使用镜像仓库中的镜像。')}}</div>
        <AppArtifactVersions v-if="isMobile" :artifacts="artifacts" :loading="artifactLoading" :loaded="artifactsLoaded" :error="artifactError" :enabled="appEnabled" :show-delivery="apps" @retry="loadArtifacts(true)" @deliver="row=>router.push(`/apps/${id}/release?artifactId=${row.id}`)"/>
        <template v-else>
        <div v-if="artifactLoading" class="artifact-list-loading" role="status">{{ tUi('正在读取制品版本…') }}</div>
        <el-alert v-else-if="artifactError" :title="artifactError" type="error" :closable="false" show-icon><template #default><el-button link type="primary" @click="loadArtifacts(true)">{{ tUi('重新读取') }}</el-button></template></el-alert>
        <el-table v-else-if="artifacts.length" :data="artifacts">
          <el-table-column :label="tUi('打包完成')" width="165"><template #default="{row}"><div class="record-time" :title="timeParts(row.createdAt).full"><b>{{timeParts(row.createdAt).time}}</b><span>{{timeParts(row.createdAt).date}}</span><small v-if="row.buildTaskId">{{ tUi('构建 #{0}', row.buildTaskId) }}</small></div></template></el-table-column>
          <el-table-column :label="tUi('分支 / Commit')" min-width="220"><template #default="{row}"><b class="record-branch" :title="row.branch">{{row.branch || tUi('未记录分支')}}</b><CommitHash :value="row.commitId"/></template></el-table-column>
          <el-table-column v-if="isMobile" :label="tUi('构建环境')" width="145"><template #default="{row}"><el-tag v-if="row.buildEnvironmentName" :type="row.buildEnvironmentName==='prod'?'danger':'warning'" effect="plain">{{environmentLabel(row.buildEnvironmentName)}}</el-tag><span v-else>{{ tUi('历史包 · 待重建') }}</span><small class="artifact-repository">{{row.buildMode || tUi('未记录模式')}}</small></template></el-table-column><el-table-column :label="isMobile?tUi('安装包版本'):tUi('镜像版本')" min-width="245"><template #default="{row}"><span class="artifact-version-label" :title="isMobile?mobileVersionLabel(row):row.version">{{isMobile?mobileVersionLabel(row):row.version}}</span><span class="artifact-repository" :title="row.imageUrl">{{row.imageUrl || (isMobile?'Android '+(row.format||tUi('安装包')):tUi('未记录镜像地址'))}}</span></template></el-table-column>
          <el-table-column :label="tUi('打包人')" width="110"><template #default="{row}">{{row.createdBy || '—'}}</template></el-table-column><el-table-column v-if="apps" :label="tUi('交付')" width="120"><template #default="{row}"><el-button link type="primary" :disabled="!appEnabled" @click="router.push(`/apps/${id}/release?artifactId=${row.id}`)">{{ tUi('创建交付') }}</el-button></template></el-table-column>
        </el-table><div v-else class="empty"><div><strong>{{ tUi('暂无制品版本') }}</strong><p>{{isMobile?tUi('安装包构建、校验并归档后，会在这里保留版本记录。'):tUi('打包成功并推送镜像后，会在这里保留版本记录。')}}</p></div></div>
        </template>
      </el-tab-pane>
      <el-tab-pane :label="apps?tUi('交付记录'):tUi('发版记录')" name="releases">
        <el-table v-if="releases.length" :data="releases" class="clickable-table" @row-click="(row: Release) => router.push(releasePath(row.id))">
          <el-table-column :label="tUi('创建时间 / 任务')" width="165"><template #default="{row}"><div class="record-time" :title="timeParts(row.createdAt).full"><b>{{timeParts(row.createdAt).time}}</b><span>{{timeParts(row.createdAt).date}}</span><small>#{{row.id}}</small></div></template></el-table-column>
          <el-table-column :label="tUi('分支 / Commit')" min-width="220"><template #default="{row}"><b class="record-branch" :title="row.branch">{{row.branch || tUi('未记录分支')}}</b><CommitHash :value="row.commitId"/></template></el-table-column>
          <el-table-column v-if="isMobile" :label="tUi('App 版本')" min-width="160"><template #default="{row}"><b>{{mobileVersionLabel(row)}}</b></template></el-table-column><el-table-column :label="tUi('环境')" width="105"><template #default="{row}"><el-tag effect="plain" size="small" :type="row.environment === 'prod' ? 'danger' : row.environment === 'test' ? 'warning' : 'info'">{{environmentLabel(row.environment)}}</el-tag></template></el-table-column>
          <el-table-column :label="tUi('状态')" width="105"><template #default="{row}"><el-tag :type="statusType(row.status)" size="small">{{statusLabel(row.status)}}</el-tag></template></el-table-column>
          <el-table-column :label="tUi('发布人')" min-width="100"><template #default="{row}">{{row.createdBy || '—'}}</template></el-table-column>
          <el-table-column :label="tUi('操作')" width="90" fixed="right"><template #default="{row}"><el-button link type="primary" @click.stop="router.push(releasePath(row.id))">{{ tUi('详情') }}</el-button></template></el-table-column>
        </el-table><div v-else class="empty"><div><strong>{{ tUi('暂无发版记录') }}</strong><p>{{ tUi('选择成功构建的制品，发起第一次发布。') }}</p></div></div>
      </el-tab-pane>
    </el-tabs>
  </section>
</template>

